import{_ as i,o as a,c as e,a2 as n}from"./chunks/framework.NpvCl_7q.js";const c=JSON.parse('{"title":"Building from source","description":"","frontmatter":{},"headers":[],"relativePath":"contributing/building.md","filePath":"contributing/building.md","lastUpdated":1792608207000}'),t={name:"contributing/building.md"};function l(h,s,p,d,o,r){return a(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="building-from-source" tabindex="-1">Building from source <a class="header-anchor" href="#building-from-source" aria-label="Permalink to &quot;Building from source&quot;">​</a></h1><p>The npm package ships prebuilt native libraries in <code>packages/nativescript-masonkit/platforms/</code>. You only need to rebuild them when you change Rust, Kotlin, Swift or C++ code. TypeScript changes only need the package rebuild at the end of this page.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Node 22 or later (CI uses 22).</li><li>Rust via <a href="https://rustup.rs" target="_blank" rel="noreferrer">rustup</a>. Keep it current with <code>rustup update</code>.</li><li><a href="https://github.com/mozilla/cbindgen" target="_blank" rel="noreferrer">cbindgen</a> (<code>cargo install cbindgen</code>). The iOS build regenerates the C headers with it on every build.</li><li>Android: the Android SDK with an NDK installed, and JDK 17.</li><li>iOS: Xcode on macOS.</li><li>Windows: see <a href="/nativescript-mason/platforms/windows#building-the-component">Windows</a>.</li></ul><p>Rust targets:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Android</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rustup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aarch64-linux-android</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> armv7-linux-androideabi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> i686-linux-android</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> x86_64-linux-android</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># iOS (device, Apple Silicon simulator, Intel simulator)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rustup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aarch64-apple-ios</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aarch64-apple-ios-sim</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> x86_64-apple-ios</span></span></code></pre></div><p>visionOS is a tier-3 Rust target with no prebuilt standard library. It builds with nightly and <code>-Z build-std</code>, so it also needs:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rustup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> toolchain</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nightly</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rustup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> component</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rust-src</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --toolchain</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nightly</span></span></code></pre></div><h2 id="android-aar" tabindex="-1">Android AAR <a class="header-anchor" href="#android-aar" aria-label="Permalink to &quot;Android AAR&quot;">​</a></h2><p>The Kotlin library builds the Rust crate itself through the <code>rust-android-gradle</code> plugin, so one Gradle command produces the whole AAR:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/nativescript-masonkit/src-native/mason-android</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :masonkit:assembleRelease</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Prust.targets=all</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> masonkit/build/outputs/aar/masonkit-release.aar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../../platforms/android/</span></span></code></pre></div><p>Or run both steps with the package script:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/nativescript-masonkit</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:android</span></span></code></pre></div><p><code>-Prust.targets</code> picks the ABIs: <code>all</code> (arm, arm64, x86, x86_64), a comma-separated list such as <code>arm64,x86_64</code>, or leave it out to build only your host architecture, which is much faster while iterating.</p><div class="warning custom-block"><p class="custom-block-title">Environment traps</p><p>Both of these fail with a one-line <code>BUILD FAILED</code> that says nothing about the cause.</p><ul><li><p><strong><code>rustc</code> and <code>cargo</code> must be on the Gradle daemon&#39;s <code>PATH</code></strong>, not just your shell&#39;s. The failure reads <code>A problem occurred starting process &#39;command &#39;rustc&#39;&#39;</code>. After changing your environment, run with <code>--no-daemon</code> (or <code>./gradlew --stop</code> first).</p></li><li><p><strong>A Rust build script runs <code>python</code>, not <code>python3</code>.</strong> On macOS <code>/usr/bin/python3</code> is an Xcode shim that fails when invoked as <code>python</code>. Put a real shim ahead of it on <code>PATH</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#!/bin/sh</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/bin/python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div></li></ul></div><div class="tip custom-block"><p class="custom-block-title">Check the AAR timestamp</p><p>A failed <code>assembleRelease</code> can leave the previous AAR in <code>masonkit/build/outputs/aar</code>. Check its modification time before copying it, or you will ship the old binary.</p></div><h2 id="ios-xcframework" tabindex="-1">iOS xcframework <a class="header-anchor" href="#ios-xcframework" aria-label="Permalink to &quot;iOS xcframework&quot;">​</a></h2><p>The Xcode project has a <strong>Build Mason Rust</strong> build phase (<code>src-native/mason-ios/Mason/pre-build.sh</code>) that regenerates the C headers with cbindgen and builds the <code>mason-ios</code> crate for each architecture Xcode is building. So the framework build is one script:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/nativescript-masonkit/src-native/mason-ios</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                      # iOS device + simulator</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">INCLUDE_VISIONOS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ./build.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # plus visionOS device + simulator</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../../platforms/ios/Mason.xcframework</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist/Mason.xcframework</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../../platforms/ios/</span></span></code></pre></div><p><code>build.sh</code> builds Release frameworks for each SDK and combines them into <code>dist/Mason.xcframework</code>.</p><p>The package script does the visionOS build and the copy in one step:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/nativescript-masonkit</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:ios</span></span></code></pre></div><p><code>npm run build:native</code> runs <code>build:android</code> and then <code>build:ios</code>.</p><div class="warning custom-block"><p class="custom-block-title">pre-build.sh reads your shell profile</p><p>The Xcode build phase runs <code>source $HOME/.cargo/env</code> and <code>source $HOME/.profile</code> under <code>set -e</code>. If either file is missing the phase fails, so make sure both exist and put <code>cargo</code>, <code>rustc</code> and <code>cbindgen</code> on <code>PATH</code> there.</p></div><h2 id="windows-component" tabindex="-1">Windows component <a class="header-anchor" href="#windows-component" aria-label="Permalink to &quot;Windows component&quot;">​</a></h2><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cd packages</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">nativescript</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">masonkit</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">src</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">native</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">windows</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pwsh .</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">publish.ps1</span></span></code></pre></div><p>This builds the <code>mason-windows</code> crate and the C++/WinRT component for x64 and ARM64 and copies the binaries into <code>platforms/windows/</code>. Prerequisites and the native test harness are on the <a href="/nativescript-mason/platforms/windows#building-the-component">Windows page</a>.</p><h2 id="manual-rust-builds" tabindex="-1">Manual Rust builds <a class="header-anchor" href="#manual-rust-builds" aria-label="Permalink to &quot;Manual Rust builds&quot;">​</a></h2><p>You rarely need these, since Gradle and Xcode drive Cargo for you. To check that a crate compiles for a target:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mason-ios</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aarch64-apple-ios</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mason-android</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aarch64-linux-android</span></span></code></pre></div><p>Building <code>mason-android</code> by hand needs the NDK&#39;s clang as the linker. If you see <code>error: linking with &#39;cc&#39; failed</code>, point Cargo at the NDK toolchain (adjust the NDK version and host to yours):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ANDROID_NDK</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ANDROID_HOME/ndk/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">version</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PATH:$ANDROID_NDK/toolchains/llvm/prebuilt/darwin-x86_64/bin</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CC_aarch64_linux_android</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">aarch64-linux-android21-clang</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> AR_aarch64_linux_android</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">llvm-ar</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CARGO_TARGET_AARCH64_LINUX_ANDROID_LINKER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">aarch64-linux-android21-clang</span></span></code></pre></div><p>The same three variables exist for <code>armv7_linux_androideabi</code> (<code>armv7a-linux-androideabi21-clang</code>), <code>i686_linux_android</code> and <code>x86_64_linux_android</code>.</p><p><code>./tools/scripts/build-headers.sh</code> regenerates every cbindgen header (iOS, Android and the C ABI) from the repo root.</p><h2 id="rebuilding-the-package" tabindex="-1">Rebuilding the package <a class="header-anchor" href="#rebuilding-the-package" aria-label="Permalink to &quot;Rebuilding the package&quot;">​</a></h2><p>The demo apps (all except <code>apps/demo</code>) consume the built package from <code>dist/</code>. After TypeScript or native changes:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nativescript-masonkit:build.all</span></span></code></pre></div><p>This compiles the TypeScript and the Angular, Vue and Svelte entry points, and copies <code>platforms/</code> into <code>dist/packages/nativescript-masonkit</code>. <code>@nx/js:tsc</code> infers ESM from the tsconfig and writes <code>&quot;type&quot;: &quot;module&quot;</code> into the dist <code>package.json</code>, which would make Node load <code>nativescript.webpack.js</code> as ESM; <code>tools/scripts/build-finish.ts</code> restores the source package&#39;s <code>type</code> and <code>module</code> fields.</p><h2 id="running-a-demo" tabindex="-1">Running a demo <a class="header-anchor" href="#running-a-demo" aria-label="Permalink to &quot;Running a demo&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/demo-solid</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ns</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ios</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ns</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> android</span></span></code></pre></div><p>Or pick a demo from the <code>npm start</code> menu. Two things to know:</p><ul><li><code>ANDROID_HOME</code> must be exported in the shell that runs <code>ns run android</code>.</li><li><code>ns run ios</code> needs <code>LANG</code> and <code>LC_ALL</code> set (for example <code>en_US.UTF-8</code>), or the CocoaPods check fails.</li></ul><p>Native library changes need <code>ns run</code> to be stopped and started again; livesync only reloads JavaScript.</p>`,43)])])}const g=i(t,[["render",l]]);export{c as __pageData,g as default};
